    #[test]
    fn recipient_from_subject_derives_the_agent() {
        // pr-sync's reply subjects — the recipient is recoverable even when to=unknown.
        assert_eq!(
            recipient_from_subject("merged: fleet/v-diagnostics").as_deref(),
            Some("v-diagnostics")
        );
        assert_eq!(
            recipient_from_subject("reject: fleet/fix-host-closure-declines").as_deref(),
            Some("fix-host-closure-declines")
        );
        // A branch token mid-sentence still resolves; trailing text after the agent stops at whitespace.
        assert_eq!(
            recipient_from_subject("integrated fleet/breaker onto trunk").as_deref(),
            Some("breaker")
        );
        // No fleet/<agent> → None (don't misroute).
        assert!(recipient_from_subject("some unrelated subject").is_none());
        // A traversal-y agent token is rejected by the name charset → None (never route to garbage).
        assert!(recipient_from_subject("merged: fleet/../etc").is_none());
        // The `[reconciled from unknown/]`-PREFIXED subject that `reroute_unknown` itself produces must
        // STILL resolve — else a re-routed note (if it ever re-hit unknown/) couldn't be re-derived, and
        // an anchored-at-start rewrite of this fn would silently break the reconciler. Pin the round-trip.
        assert_eq!(
            recipient_from_subject("[reconciled from unknown/] merged: fleet/v-quantity")
                .as_deref(),
            Some("v-quantity")
        );
    }

    #[test]
    fn sender_from_branch_name_maps_branch_to_agent() {
        // A vertical/fix agent's worktree is on `fleet/<agent>` → that branch names the sender. This is
        // the `--from` derivation that keeps pr-sync's replies from dead-lettering to `unknown`.
        assert_eq!(
            sender_from_branch_name("fleet/v-fleet-tooling").as_deref(),
            Some("v-fleet-tooling")
        );
        assert_eq!(
            sender_from_branch_name("fleet/fix-two-string-payloads").as_deref(),
            Some("fix-two-string-payloads")
        );
        // pr-sync runs on `trunk` itself.
        assert_eq!(sender_from_branch_name("trunk").as_deref(), Some("pr-sync"));
        // Neither a fleet/ branch nor trunk → None (caller falls back to `unknown`), and an empty
        // string (detached HEAD prints nothing) → None, never a bogus sender.
        assert!(sender_from_branch_name("main").is_none());
        assert!(sender_from_branch_name("some-feature").is_none());
        assert!(sender_from_branch_name("").is_none());
        // A `fleet/<garbage>` branch must NOT resolve to a garbage/traversal sender (name charset guard).
        assert!(sender_from_branch_name("fleet/../etc").is_none());
        assert!(sender_from_branch_name("fleet/").is_none());
        assert!(sender_from_branch_name("fleet/a b").is_none());
    }

    #[test]
    fn agent_for_worktree_path_matches_the_registry_entry_owning_this_checkout() {
        // The branch-INDEPENDENT fallback (v-effects PR-branch bug): a sender on a feature branch that
        // `sender_from_branch` can't map still resolves by its worktree PATH via the registry.
        let agents = [
            ("v-effects", PathBuf::from("/wt/v-effects")),
            ("v-fleet-tooling", PathBuf::from("/wt/v-fleet-tooling")),
        ];
        assert_eq!(
            agent_for_worktree_path(&agents, Path::new("/wt/v-effects")).as_deref(),
            Some("v-effects"),
            "the worktree owning this checkout names the sender, regardless of the branch"
        );
        // A path that no registry entry owns → None (caller falls to `unknown`).
        assert!(agent_for_worktree_path(&agents, Path::new("/wt/not-an-agent")).is_none());
        // A garbage registry name must NOT resolve a sender (same charset guard as the branch path).
        let garbage = [("../etc", PathBuf::from("/wt/x"))];
        assert!(agent_for_worktree_path(&garbage, Path::new("/wt/x")).is_none());
    }

    #[test]
    fn urgency_validation_and_tag() {
        // Every declared level validates; a typo is refused at the source (fleet send exits non-zero).
        for lvl in ["low", "normal", "high", "urgent"] {
            assert!(is_valid_urgency(lvl), "{lvl} is a valid level");
        }
        assert!(!is_valid_urgency("URGENT"), "levels are case-sensitive");
        assert!(!is_valid_urgency("critical"), "an unknown level is refused");
        assert!(!is_valid_urgency(""), "empty is not a level");
        // A pre-urgency message with no field deserializes to the default.
        assert_eq!(default_urgency(), "normal");
        // Only elevated levels get a loud inbox tag; normal/low/unknown stay untagged so the common
        // row is unchanged (the tag is a genuine prioritize-this signal, not per-row noise).
        assert_eq!(urgency_tag("urgent"), "  <<URGENT>>");
        assert_eq!(urgency_tag("high"), "  <high>");
        assert_eq!(urgency_tag("normal"), "");
        assert_eq!(urgency_tag("low"), "");
        assert_eq!(urgency_tag("mystery"), "");
    }

    #[test]
    fn message_urgency_is_back_compatible_and_round_trips() {
        // A message JSON WITHOUT an urgency field (pre-feature) must parse (serde default = normal).
        let old = r#"{"from":"a","to":"b","kind":"note","subject":"s","seq":1}"#;
        let m: Message = serde_json::from_str(old).expect("pre-urgency message still parses");
        assert_eq!(m.urgency, "normal", "absent field defaults to normal");
        // A message WITH urgency round-trips.
        let with = r#"{"from":"a","to":"b","kind":"ask","subject":"s","seq":1,"urgency":"urgent"}"#;
        let m2: Message = serde_json::from_str(with).expect("urgent message parses");
        assert_eq!(m2.urgency, "urgent");
    }

    #[test]
    fn materialize_source_deploys_disk_hygiene_scripts_executable_into_the_hub() {
        // Pins the deploy invariant (#3793 target-dir tool + the /tmp-inode tool): `fleet up` must
        // materialize each tracked disk-hygiene script from `fleet/` into the hub runtime dir WITH the
        // executable bit — the concierge's maintenance cron calls the HUB copies, so a refactor that
        // drops one from the materialize set (or its chmod) would silently point the cron at a
        // stale/absent/non-exec file.
        let scripts = [
            "prune-stale-targets.sh",
            "prune-tmp-inodes.sh",
            "reap-wedged-nix-clients.sh",
            "refresh-tools.sh",
            "cargo-nix-shim.sh",
            "nix-shim.sh",
            "cpu-monitor.sh",
        ];
        let base = std::env::temp_dir().join(format!("cdz-materialize-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        let src = base.join("fleet");
        let root = base.join("hub");
        std::fs::create_dir_all(&src).unwrap();
        std::fs::create_dir_all(&root).unwrap();
        for s in scripts {
            std::fs::write(src.join(s), format!("#!/usr/bin/env bash\necho {s}\n")).unwrap();
        }

        let fleet = Fleet {
            root: root.clone(),
            worktrees: root.join("worktrees"),
            repo: PathBuf::from("/hub"),
            src: src.clone(),
        };
        fleet.materialize_source();

        for s in scripts {
            let dst = root.join(s);
            assert!(dst.exists(), "{s} is materialized into the hub");
            assert_eq!(
                std::fs::read_to_string(&dst).unwrap(),
                format!("#!/usr/bin/env bash\necho {s}\n"),
                "{s} content is copied verbatim"
            );
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                let mode = std::fs::metadata(&dst).unwrap().permissions().mode() & 0o777;
                assert_eq!(mode, 0o755, "the materialized {s} gets the executable bit");
            }
        }
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn heartbeat_does_not_refresh_liveness_for_a_stopped_agent() {
        // Concierge robustness report: a still-in-flight tick that heartbeats AFTER `fleet remove` must
        // not make the just-removed agent look freshly-alive. So when the stop-file is present, the
        // liveness touch-file is left UNTOUCHED and the caller is told to stand down.
        let root = std::env::temp_dir().join(format!("cdz-hb-stopped-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();
        let fleet = Fleet {
            root: root.clone(),
            worktrees: root.join("worktrees"),
            repo: PathBuf::from("/hub"),
            src: PathBuf::from("/wt/fleet"),
        };
        let hb = root.join("heartbeat").join("v-x");

        // Live agent (no stop-file): heartbeat refreshes liveness and does NOT stand down.
        assert!(
            !heartbeat_refresh_liveness(&fleet, "v-x"),
            "a live agent is not stopped"
        );
        assert!(
            hb.exists(),
            "a live heartbeat writes the liveness touch-file"
        );

        // Remove drops a stop-file; delete the touch-file to prove the next heartbeat does NOT re-create it.
        std::fs::create_dir_all(fleet.stopfile("v-x").parent().unwrap()).unwrap();
        std::fs::write(fleet.stopfile("v-x"), "removed\n").unwrap();
        std::fs::remove_file(&hb).unwrap();
        assert!(
            heartbeat_refresh_liveness(&fleet, "v-x"),
            "a stopped agent's heartbeat reports stopped (caller stands down)"
        );
        assert!(
            !hb.exists(),
            "a stopped agent's heartbeat must NOT refresh liveness — no touch-file re-created"
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn agent_name_rejects_path_traversal_and_non_roster_chars() {
        // The PR#391 class: a name that escapes the inbox tree must be refused — plus dots/underscores
        // (no real name uses them, and a dot is what enables the `..` traversal), matching the Slack
        // bridge's stricter `^[A-Za-z0-9][A-Za-z0-9-]*$`.
        for bad in [
            "..",
            ".",
            "../x",
            "../../etc",
            "a/b",
            "a\\b",
            "/abs",
            "",
            ".hidden",     // leading dot (dotfile-lookalike)
            "-flag",       // leading dash (flag-lookalike)
            "a..b",        // embedded `..`
            "a.b",         // any dot now rejected (aligns with the bridge)
            "a_b",         // underscore now rejected (no roster name uses one)
            "fix-pr391.2", // dot rejected
            "a b",         // space (not in the charset)
            "a\0b",        // NUL
        ] {
            assert!(validate_agent_name(bad).is_err(), "should reject {bad:?}");
        }
    }

