    #[test]
    fn in_reply_to_round_trips_and_is_omitted_when_empty() {
        // A reply from `fleet ack` carries the resolved request's filename so `fleet audit` can pair
        // them; a plain message omits the field entirely (so old JSON stays readable + diffs stay clean).
        let reply = Message {
            from: "pr-sync".into(),
            to: "v-x".into(),
            kind: "merged".into(),
            subject: "merged: fleet/v-x".into(),
            r#ref: "trunk@abc".into(),
            body: "ok".into(),
            seq: 1,
            in_reply_to: "000000000001-42-merge-request.json".into(),
            urgency: default_urgency(),
        };
        let json = serde_json::to_string(&reply).unwrap();
        assert!(json.contains("in_reply_to"));
        let back: Message = serde_json::from_str(&json).unwrap();
        assert_eq!(back.in_reply_to, "000000000001-42-merge-request.json");

        let plain = Message {
            in_reply_to: String::new(),
            ..reply
        };
        let json = serde_json::to_string(&plain).unwrap();
        assert!(!json.contains("in_reply_to"), "empty field must be omitted");
        // And a message with NO in_reply_to key deserializes fine (default).
        let old: Message =
            serde_json::from_str(r#"{"from":"a","to":"b","kind":"note","subject":"s","seq":9}"#)
                .unwrap();
        assert_eq!(old.in_reply_to, "");
    }

    #[test]
    fn merged_floor_takes_field_wise_max() {
        // The driver's whole reason to exist: two agents each bumped the monotone floor, so the merge
        // must be the field-wise MAX of both sides — never one side clobbering the other's higher count.
        let ours = serde_json::json!({"cited": 645, "total": 900});
        let theirs = serde_json::json!({"cited": 644, "total": 901});
        let m = merged_floor_value(ours, &theirs).expect("two objects merge");
        assert_eq!(m.get("cited").and_then(|n| n.as_u64()), Some(645)); // ours higher
        assert_eq!(m.get("total").and_then(|n| n.as_u64()), Some(901)); // theirs higher
    }

    #[test]
    fn merged_floor_is_symmetric_and_idempotent() {
        // max is commutative, so which side is `ours` must not change the merged counters (only which
        // side's extra keys survive) — and merging a value with itself is a no-op.
        let a = serde_json::json!({"cited": 10, "total": 20});
        let b = serde_json::json!({"cited": 30, "total": 15});
        let ab = merged_floor_value(a.clone(), &b).expect("objects merge");
        let ba = merged_floor_value(b.clone(), &a).expect("objects merge");
        assert_eq!(ab.get("cited"), ba.get("cited"));
        assert_eq!(ab.get("total"), ba.get("total"));
        assert_eq!(ab.get("cited").and_then(|n| n.as_u64()), Some(30));
        assert_eq!(ab.get("total").and_then(|n| n.as_u64()), Some(20));
        let self_merged = merged_floor_value(a.clone(), &a).expect("objects merge");
        assert_eq!(self_merged.get("cited").and_then(|n| n.as_u64()), Some(10));
        assert_eq!(self_merged.get("total").and_then(|n| n.as_u64()), Some(20));
    }

    #[test]
    fn merged_floor_preserves_ours_extra_keys() {
        // Ours' non-counter fields (e.g. the `_note` describing the file) must survive the merge —
        // the driver rewrites only `cited`/`total`, everything else on ours is kept verbatim.
        let ours =
            serde_json::json!({"cited": 1, "total": 2, "_note": "coverage floor — do not lower"});
        let theirs = serde_json::json!({"cited": 5, "total": 5});
        let m = merged_floor_value(ours, &theirs).expect("objects merge");
        assert_eq!(
            m.get("_note").and_then(|s| s.as_str()),
            Some("coverage floor — do not lower")
        );
        assert_eq!(m.get("cited").and_then(|n| n.as_u64()), Some(5));
    }

    #[test]
    fn merged_floor_missing_or_garbage_counter_reads_as_zero() {
        // A missing/non-numeric counter must read as 0 so the OTHER side wins, never poisoning the
        // merged floor to 0 or panicking. (A monotone floor should never regress to 0 by a bad merge.)
        let ours = serde_json::json!({"total": 900}); // no `cited`
        let theirs = serde_json::json!({"cited": 644, "total": "oops"}); // garbage `total`
        let m = merged_floor_value(ours, &theirs).expect("objects merge (garbage counters ok)");
        assert_eq!(m.get("cited").and_then(|n| n.as_u64()), Some(644)); // theirs, ours missing→0
        assert_eq!(m.get("total").and_then(|n| n.as_u64()), Some(900)); // ours, theirs garbage→0
    }

    #[test]
    fn merged_floor_rejects_a_valid_json_non_object() {
        // PR #430: a floor file that is valid JSON but NOT an object (null, a number, an array, a
        // string) is a corrupt/wrong floor. The driver must NOT "resolve" the conflict by rewriting it
        // (or returning it unchanged) — it must decline (None) so merge_floor leaves the conflict for a
        // human. Distinct from missing/garbage COUNTERS inside an object (those correctly read as 0).
        let obj = serde_json::json!({"cited": 5, "total": 5});
        for bad in [
            serde_json::Value::Null,
            serde_json::json!(42),
            serde_json::json!("644"),
            serde_json::json!([1, 2, 3]),
            serde_json::json!(true),
        ] {
            // Either side being a non-object declines.
            assert!(
                merged_floor_value(bad.clone(), &obj).is_none(),
                "ours={bad:?} must decline"
            );
            assert!(
                merged_floor_value(obj.clone(), &bad).is_none(),
                "theirs={bad:?} must decline"
            );
        }
        // Two non-objects also decline (never rewrite).
        assert!(merged_floor_value(serde_json::Value::Null, &serde_json::json!(0)).is_none());
    }

    #[test]
    fn maxfloor_driver_is_worktree_portable() {
        // PR #426: the driver value lives in the hub-shared .git/config but a merge can run from ANY
        // worktree, each with its OWN target/. So the command must NOT embed an absolute path or a
        // `target/` binary (current_exe()'s form) — it must resolve via the tracked `cargo xtask`
        // alias from whatever worktree git runs the merge in.
        let cmd = maxfloor_driver_command();
        assert!(
            cmd.starts_with("cargo xtask "),
            "driver must invoke the portable cargo alias, got {cmd:?}"
        );
        assert!(
            !cmd.contains("target/") && !cmd.contains('/'),
            "driver must not bake in a worktree-local path, got {cmd:?}"
        );
        // git substitutes the two conflicting versions into %A (ours/result) and %B (theirs).
        assert!(
            cmd.contains("%A") && cmd.contains("%B"),
            "driver needs the %A/%B placeholders"
        );
        assert!(
            cmd.contains("fleet merge-floor"),
            "driver must call the merge-floor subcommand"
        );
    }

    #[test]
    fn rearm_escalates_only_when_a_prior_nudge_didnt_stick() {
        use RearmAction::*;
        // (rearm_age, hb_age) — both "seconds ago", larger = older, None = never.

        // Never re-armed but HAS heartbeated before → a healthy looping agent that merely missed a
        // tick → first-time cheap nudge.
        assert_eq!(rearm_action(None, Some(900)), NudgeContinue);
        // DEAD-CRON COLD-START (option iii): never re-armed AND never heartbeated → the fresh-mint
        // whose initial `/loop` cron never armed. A `continue` would tick once (stamping a heartbeat
        // that MASKS the dead cron) then freeze again → perpetual nudge-loop. Escalate straight to
        // `/loop` on first contact to ARM a self-sustaining cron.
        assert_eq!(rearm_action(None, None), ReissueLoop);

        // Re-armed, and NO heartbeat since (hb older-or-equal than the re-arm) → the nudge didn't stick
        // → escalate to arm a cron. (hb_age 900 ≥ rearm_age 300 ⟹ last tick predates the re-arm.)
        assert_eq!(rearm_action(Some(300), Some(900)), ReissueLoop);
        // Re-armed and NEVER heartbeated → definitely didn't stick → escalate.
        assert_eq!(rearm_action(Some(300), None), ReissueLoop);
        // Equal ages (can't prove a tick landed after) → escalate (conservative).
        assert_eq!(rearm_action(Some(300), Some(300)), ReissueLoop);

        // THE BUG THIS GUARDS: an agent re-armed long ago that RECOVERED and has heartbeated SINCE
        // (hb_age 60 < rearm_age 3600) must get a cheap nudge on a fresh stall — NOT a `/loop` re-issue.
        // The rearm marker is never cleared, so keying on "ever re-armed" would wrongly escalate here.
        assert_eq!(rearm_action(Some(3600), Some(60)), NudgeContinue);
    }

    #[test]
    fn repeated_nudge_escalates_a_dead_cron_masked_by_nudge_heartbeats() {
        use RearmAction::*;
        let t = REPEATED_NUDGE_ESCALATE_THRESHOLD; // 2
        // The concierge case (v-lsp/v-des/v-value-facts): rearm_action keeps returning NudgeContinue
        // (hb < ra, because each nudge stamps a heartbeat), so the base verdict alone loops forever.
        // Once the CONSECUTIVE-nudge streak reaches the threshold, escalate to arm a real cron.
        assert_eq!(escalate_repeated_nudge(NudgeContinue, 0, t), NudgeContinue); // first stall → nudge
        assert_eq!(escalate_repeated_nudge(NudgeContinue, 1, t), NudgeContinue); // one prior nudge → still nudge
        assert_eq!(escalate_repeated_nudge(NudgeContinue, 2, t), ReissueLoop); // 2nd consecutive → dead cron, re-issue
        assert_eq!(escalate_repeated_nudge(NudgeContinue, 5, t), ReissueLoop); // well past → re-issue
        // An already-escalated ReissueLoop is never downgraded, regardless of streak.
        assert_eq!(escalate_repeated_nudge(ReissueLoop, 0, t), ReissueLoop);
        assert_eq!(escalate_repeated_nudge(ReissueLoop, 9, t), ReissueLoop);
        // Boundary: exactly at the threshold escalates; one below stays a nudge (a single genuinely-
        // missed tick — streak 1 — still gets the cheap nudge first, not an immediate re-issue).
        assert_eq!(
            escalate_repeated_nudge(NudgeContinue, t - 1, t),
            NudgeContinue
        );
        assert_eq!(escalate_repeated_nudge(NudgeContinue, t, t), ReissueLoop);
    }

    #[test]
    fn nudge_streak_clears_only_when_heartbeat_is_a_self_tick_after_the_nudge() {
        let interval = 1800; // 30m agent
        // Never re-armed → any fresh heartbeat is self-produced → clear.
        assert!(should_clear_nudge_streak(None, Some(60), interval));
        assert!(should_clear_nudge_streak(None, None, interval));

        // THE ROUND-3 BUG (concierge): on the idle-re-arm path the re-arm + heartbeat are stamped
        // TOGETHER by the nudge, so a dead-cron agent has hb_age ≈ rearm_age — they age in LOCKSTEP.
        // The clear must NOT fire for that, else the streak resets between every nudge + never escalates.
        // hb_age ≈ rearm_age (both from the same nudge, aging together) → DON'T clear, whatever the age:
        assert!(!should_clear_nudge_streak(Some(120), Some(115), interval)); // just nudged, lockstep
        assert!(!should_clear_nudge_streak(Some(2400), Some(2395), interval)); // ~stale boundary, still lockstep
        assert!(!should_clear_nudge_streak(Some(2400), Some(2400), interval)); // exactly equal
        // The OLD stale_after threshold wrongly cleared this (rearm_age 2400 > stale) — now it correctly
        // does NOT, because the heartbeat is NOT a self-tick (hb_age tracks rearm_age).

        // GENUINE SELF-TICK: heartbeat ≥ one interval NEWER than the re-arm → the cron fired on its own
        // AFTER the nudge → clear (streak must not accrue for a healthy agent).
        assert!(should_clear_nudge_streak(Some(2400), Some(60), interval)); // nudged 40m ago, self-ticked 1m ago
        assert!(should_clear_nudge_streak(Some(3600), Some(300), interval)); // hb 55m newer than rearm
        // Boundary: exactly one interval newer → clear; just under → not yet.
        assert!(should_clear_nudge_streak(Some(1860), Some(60), interval)); // 1860 >= 60+1800 → clear
        assert!(!should_clear_nudge_streak(Some(1859), Some(60), interval)); // 1859 < 60+1800 → don't

        // Re-armed but NEVER heartbeated since → not self-sustaining → keep the streak.
        assert!(!should_clear_nudge_streak(Some(300), None, interval));
    }

    #[test]
    fn stale_watchdog_warning_fires_only_when_the_xtask_source_lags_trunk() {
        // Up to date → quiet (a healthy sweep must not spam the warning).
        assert!(stale_watchdog_warning(0).is_none());
        // Behind by ANY amount → warn, and the message must name the lag + the self-serve remedy so a
        // reader (or the concierge) knows to sync+rebuild — this is the whole point of the guard (the
        // dead-cron saga's real cause was a 12-behind watchdog binary that silently ran old logic).
        let w = stale_watchdog_warning(12).expect("12 behind → warns");
        assert!(w.contains("12"), "warning must state how far behind: {w}");
        assert!(
            w.contains("BEHIND") && w.contains("rebuild"),
            "warning must flag staleness + the rebuild remedy: {w}"
        );
        // Single-commit lag still fires (no silent tolerance band — one missing fix is enough).
        assert!(stale_watchdog_warning(1).is_some());
    }

    #[test]
    fn stale_base_reject_guidance_branches_on_baseline_vs_same_file() {
        // A .gate-baseline* conflict → the append-not-rewrite cure + names the file.
        let g = stale_base_reject_guidance("spec/semantics/.gate-baseline-rust-async\n");
        assert!(g.contains("BASELINE conflict"), "baseline branch: {g}");
        assert!(g.contains("APPEND"), "baseline cure = append: {g}");
        assert!(
            g.contains("spec/semantics/.gate-baseline-rust-async"),
            "names the conflicted file: {g}"
        );
        // A non-baseline (source/test) conflict → the same-file-region / batch-or-space cure.
        let s = stale_base_reject_guidance(
            "implementation/seed/crates/rcdzc/src/backend/rust/tests.rs\n",
        );
        assert!(s.contains("same-file-region"), "non-baseline branch: {s}");
        assert!(
            s.contains("batch") && s.contains("space"),
            "same-file cure = batch/space: {s}"
        );
        assert!(
            !s.contains("BASELINE conflict"),
            "must not mislabel a test file as baseline: {s}"
        );
        // MIXED (baseline + other) → baseline cure wins (the union-unmergeable rewrite is the blocker).
        let m = stale_base_reject_guidance("spec/semantics/.gate-baseline\nsrc/foo.rs\n");
        assert!(
            m.contains("BASELINE conflict"),
            "mixed → baseline cure: {m}"
        );
        // Empty conflict list (git gave nothing) → still a valid stale-base reject, no file note, no panic.
        let e = stale_base_reject_guidance("");
        assert!(e.contains("stale-base"), "always a stale-base reject: {e}");
        assert!(
            !e.contains("Conflicted:"),
            "no dangling file note when empty: {e}"
        );
        // Blank/whitespace lines are ignored (git output padding doesn't create phantom files).
        let w = stale_base_reject_guidance("\n  \n");
        assert!(
            !w.contains("Conflicted:"),
            "whitespace-only → no file note: {w}"
        );
    }

    #[test]
    fn merge_base_range_anchors_on_merge_base_else_falls_back_to_trunk() {
        // Merge-base resolved → range is merge-base..ref (the ref's own commits since origin/main),
        // NOT trunk..ref — immune to a stale/commit-distinct local trunk (the false-conflict fix).
        assert_eq!(
            merge_base_range(Some("abc123"), "deadbeef"),
            "abc123..deadbeef"
        );
        // Merge-base unresolved (None) → legacy trunk..ref fallback (rev-list faces report a bad ref).
        assert_eq!(merge_base_range(None, "deadbeef"), "trunk..deadbeef");
        // Empty merge-base string (git printed nothing) is treated as unresolved → trunk fallback, never
        // "..ref" (which would resolve to the ref's whole history from the root — a huge wrong range).
        assert_eq!(merge_base_range(Some(""), "deadbeef"), "trunk..deadbeef");
    }

    #[test]
    fn pane_busy_is_trusted_only_when_the_agent_has_ever_heartbeated() {
        // A has-looped agent (heartbeat stamped ≥once) with a busy pane is genuinely mid-tick → trust
        // the pane, skip re-arm (never interrupt real work).
        assert!(pane_busy_means_working(true, true));
        // A has-looped agent whose pane is idle → not working → don't skip on this guard.
        assert!(!pane_busy_means_working(true, false));
        // A NEVER-heartbeated agent (past cold-start) with a BUSY pane is FLAILING, not working — the
        // origin/trunk-flail false-positive. Its pane must NOT be trusted, so re-arm proceeds.
        assert!(!pane_busy_means_working(false, true));
        // Never-heartbeated + idle pane: also not "working"; re-arm proceeds.
        assert!(!pane_busy_means_working(false, false));
    }

    #[test]
    fn watchdog_tick_prompt_mirrors_the_kickoff_contract() {
        // The re-issued loop must run the SAME contract as a freshly-launched window (heartbeat → drain
        // inbox → one gated unit of work), addressed to THIS agent's name/role/worktree/inbox.
        let fleet = Fleet {
            root: PathBuf::from("/hub/.claude/fleet"),
            worktrees: PathBuf::from("/hub/.claude/worktrees"),
            repo: PathBuf::from("/hub"),
            src: PathBuf::from("/wt/fleet"),
        };
        let a = Agent {
            name: "fix-float-compare".into(),
            role: "fix".into(),
            vertical: String::new(),
            area: String::new(),
            worktree: "/wt/fix-float-compare".into(),
            branch: "fleet/fix-float-compare".into(),
            interval: "10m".into(),
            model: "opus".into(),
            effort: "high".into(),
            status: "active".into(),
            disallow_ask: true,
        };
        let p = watchdog_tick_prompt(&fleet, &a);
        assert!(p.contains("cargo xtask fleet heartbeat fix-float-compare"));
        assert!(p.contains("drain your inbox"));
        // Step-2 must name the RESOLVER (`fleet inbox <name>`), NOT a bare inbox path — handing a path
        // invites a worktree-relative glob that hits an empty shadow dir and silently stalls the drain
        // (the v-syntax report). And it must carry the anti-glob warning so the agent can't regress to it.
        assert!(p.contains("cargo xtask fleet inbox fix-float-compare"));
        assert!(p.contains("NEVER ls a worktree-relative"));
        assert!(!p.contains("inbox/fix-float-compare/"));
        assert!(p.contains("/wt/fix-float-compare/fleet/loops/fix.md"));
        assert!(p.contains("never wait for a reply"));
        // A role with no vertical must NOT emit the vertical clause.
        assert!(!p.contains("Your vertical is"));
    }

