    #[test]
    fn shell_quote_wraps_and_escapes_for_eval() {
        // `describe` emits KEY='<value>' lines that window.sh `eval`s, so shell_quote MUST produce a
        // literal that a POSIX shell reads back as the exact input — no expansion, no injection. A plain
        // value is just single-quoted; an embedded single quote uses the POSIX close-reopen idiom
        // ('\'') since a single-quoted string can't contain a quote. (Each expected literal below was
        // verified to round-trip through a real `sh -c` in this slice.)
        assert_eq!(shell_quote("plain"), "'plain'");
        assert_eq!(shell_quote("with space"), "'with space'");
        // A metacharacter payload stays inert (single quotes suppress $(...)/`...`/$VAR expansion).
        assert_eq!(shell_quote("$(evil)"), "'$(evil)'");
        assert_eq!(shell_quote("`evil`"), "'`evil`'");
        // The load-bearing case: an embedded single quote → close, escaped-quote, reopen.
        assert_eq!(shell_quote("a'b"), "'a'\\''b'");
        assert_eq!(shell_quote("a'b'c"), "'a'\\''b'\\''c'");
        // Empty string is a valid empty quoted literal (not nothing) — else `eval` would drop the arg.
        assert_eq!(shell_quote(""), "''");
    }

    #[test]
    fn resolve_model_maps_aliases_and_passes_through() {
        // The ONE place the long 1M-context ids live — the roster/`--model` carries short aliases and
        // window.sh hands the resolved id to `claude --model`. A wrong mapping runs every agent on the
        // wrong model, so pin the two aliases and the pass-through (a full id / future model is used
        // verbatim, never mangled).
        assert_eq!(resolve_model("opus"), "us.anthropic.claude-opus-4-8[1m]");
        assert_eq!(resolve_model("fable"), "us.anthropic.claude-fable-5[1m]");
        // A non-alias (already a full id, or an unknown/future model) passes through unchanged.
        assert_eq!(
            resolve_model("us.anthropic.claude-opus-4-8[1m]"),
            "us.anthropic.claude-opus-4-8[1m]"
        );
        assert_eq!(resolve_model("some-future-model"), "some-future-model");
        assert_eq!(resolve_model(""), "");
    }

    #[test]
    fn agent_from_roster_derives_branch_worktree_and_disallow_ask() {
        let fleet = Fleet {
            root: PathBuf::from("/hub/.claude/fleet"),
            worktrees: PathBuf::from("/hub/.claude/worktrees"),
            repo: PathBuf::from("/hub"),
            src: PathBuf::from("/wt/fleet"),
        };
        let entry = |name: &str, role: &str| RosterEntry {
            name: name.into(),
            role: role.into(),
            vertical: String::new(),
            area: String::new(),
            interval: "10m".into(),
            model: "opus".into(),
            effort: "high".into(),
        };

        // A vertical/fix agent: branch = fleet/<name>, worktree = worktrees/<name>, active.
        let v = agent_from_roster(&fleet, &entry("v-fleet-tooling", "vertical"));
        assert_eq!(v.branch, "fleet/v-fleet-tooling");
        assert_eq!(v.worktree, "/hub/.claude/worktrees/v-fleet-tooling");
        assert_eq!(v.status, "active");

        // pr-sync is the ONE agent on `trunk` itself (it integrates there), not a fleet/ branch.
        let ps = agent_from_roster(&fleet, &entry("pr-sync", "pr-sync"));
        assert_eq!(ps.branch, "trunk");

        // SAFETY INVARIANT: disallow_ask is FALSE only for the TERMINAL-INTERACTIVE role (`design`) —
        // the on-demand session a human types into at the terminal, which may pop an AskUserQuestion.
        // The `concierge` is Slack-first now (operator directive 2026-08-01): it surfaces asks through
        // the bridge, so it too is DENIED the terminal prompt like every unattended role. EVERY role but
        // `design` MUST be denied that tool (window.sh passes --disallowedTools AskUserQuestion), else an
        // unattended agent could block its window forever on a human prompt.
        assert!(!agent_from_roster(&fleet, &entry("design", "design")).disallow_ask);
        assert!(
            agent_from_roster(&fleet, &entry("concierge", "concierge")).disallow_ask,
            "concierge is Slack-first — it MUST be denied the terminal AskUserQuestion"
        );
        for unattended in [
            "vertical",
            "fix",
            "pr-sync",
            "breaker",
            "fuzzer",
            "corpus-bugfix",
            "concierge",
        ] {
            assert!(
                agent_from_roster(&fleet, &entry("x", unattended)).disallow_ask,
                "role {unattended:?} is not terminal-interactive and MUST disallow AskUserQuestion"
            );
        }
    }

    #[test]
    fn count_dir_counts_matching_top_level_files_only() {
        // count_dir backs the board's inbox-depth (`N msg`). Its invariants matter: it must count only
        // immediate FILES matching `keep`, and must NOT descend into subdirs — the inbox holds a
        // `processed/` archive, and counting it would massively over-report the live backlog.
        // Unique per-process dir so concurrent `cargo test` runs (or a prior crashed run) can't collide
        // on a shared fixed name (PR #444). pid is stable within this test process and distinct across
        // concurrent ones.
        let base = std::env::temp_dir().join(format!("cdz-count-dir-test-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base); // clean any stale dir from a prior run of THIS pid
        std::fs::create_dir_all(&base).unwrap();
        // Two live .json messages + a non-.json file (should be skipped by the `keep` predicate).
        std::fs::write(base.join("000000000001-1-merge-request.json"), "{}").unwrap();
        std::fs::write(base.join("000000000001-2-note.json"), "{}").unwrap();
        std::fs::write(base.join("README.txt"), "x").unwrap();
        // A processed/ subdir with its own .json files — count_dir must NOT descend into it.
        std::fs::create_dir_all(base.join("processed")).unwrap();
        std::fs::write(base.join("processed/000000000001-0-old.json"), "{}").unwrap();
        std::fs::write(base.join("processed/000000000001-9-old.json"), "{}").unwrap();

        // Only the two top-level .json files count (not README.txt, not the subdir or its contents).
        assert_eq!(count_dir(&base, |f| f.ends_with(".json")), 2);
        // A predicate that matches nothing → 0 (not an error).
        assert_eq!(count_dir(&base, |f| f.ends_with(".sexp")), 0);
        // A missing dir → 0, never a panic (an agent with no inbox yet reads as empty).
        assert_eq!(count_dir(&base.join("does-not-exist"), |_| true), 0);

        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn roster_entry_json_excludes_ephemeral_and_omits_empty_fields() {
        let agent = |name: &str, role: &str, status: &str, vertical: &str, area: &str| Agent {
            name: name.into(),
            role: role.into(),
            vertical: vertical.into(),
            area: area.into(),
            worktree: format!("/wt/{name}"),
            branch: format!("fleet/{name}"),
            interval: "10m".into(),
            model: "opus".into(),
            effort: "high".into(),
            status: status.into(),
            disallow_ask: true,
        };

        // An active vertical is persisted, with its vertical+area fields present.
        let line = roster_entry_json(&agent(
            "v-iterators",
            "vertical",
            "active",
            "iterators",
            "rcdzc",
        ))
        .expect("active vertical is persisted");
        assert!(line.contains("\"name\": \"v-iterators\""));
        assert!(line.contains("\"role\": \"vertical\""));
        assert!(line.contains("\"vertical\": \"iterators\""));
        assert!(line.contains("\"area\": \"rcdzc\""));
        assert!(line.contains("\"model\": \"opus\""));

        // EXCLUSION invariant: ephemeral roles must NOT be persisted (else `fleet up` revives dead/
        // transient agents). fix = minted-per-bug; design = interactive/hand-started.
        assert!(roster_entry_json(&agent("fix-x", "fix", "active", "", "")).is_none());
        assert!(roster_entry_json(&agent("design", "design", "active", "", "")).is_none());
        // A non-active agent (stopped/removed) is not persisted either.
        assert!(roster_entry_json(&agent("v-old", "vertical", "stopped", "", "")).is_none());

        // Field omission: an agent with no vertical/area omits those keys (minimal, diff-stable file).
        let bare = roster_entry_json(&agent("pr-sync", "pr-sync", "active", "", ""))
            .expect("active pr-sync is persisted");
        assert!(
            !bare.contains("\"vertical\""),
            "empty vertical must be omitted: {bare}"
        );
        assert!(
            !bare.contains("\"area\""),
            "empty area must be omitted: {bare}"
        );
    }

    #[test]
    fn informational_msg_is_spent_reaps_only_provably_spent_mail() {
        let queued = vec!["abc123def".to_string(), "999ffff".to_string()];
        let fresh = 60u64; // 1 min old — well under the 24h audit-log threshold.
        let old = NOTE_AUDIT_LOG_AGE + 1; // past the audit-log threshold.
        // INERT ACKS → always spent (safe to reap), regardless of ref/subject/age.
        for kind in ["merged", "status", "backlog", "reply"] {
            assert!(
                informational_msg_is_spent(kind, "anything", "", &queued, fresh),
                "{kind} ack is always spent"
            );
        }
        // A DROP-directive note whose ref has LEFT the queue → SPENT (drop took effect, can't re-land).
        assert!(informational_msg_is_spent(
            "note",
            "DROP-REF deadbeef: superseded",
            "deadbeef",
            &queued,
            fresh
        ));
        // A DROP-directive note whose ref is STILL queued → NOT spent (load-bearing: refs_to_drop reads it
        // to filter the queue; reaping now would let the withdrawn MR re-land = double-land regression).
        assert!(!informational_msg_is_spent(
            "note",
            "DROP-REF abc123def: superseded",
            "abc123def",
            &queued,
            fresh
        ));
        // ref-match is prefix-symmetric (short vs full sha) — a short drop-ref still matches a queued full sha.
        assert!(!informational_msg_is_spent(
            "note",
            "DROP-REF abc123",
            "abc123",
            &queued,
            fresh
        ));
        // CRUCIAL: even AGED past the audit-log threshold, a note whose structured ref is STILL QUEUED is
        // NEVER age-reaped — age must not override the double-land guard.
        assert!(!informational_msg_is_spent(
            "note",
            "DROP-REF abc123def: superseded",
            "abc123def",
            &queued,
            old
        ));
        // A FRESH real coordination note (not a drop-directive) → NOT spent — left to keep escalating.
        assert!(!informational_msg_is_spent(
            "note",
            "heads-up: cutover plan for the S3 flag-day",
            "",
            &queued,
            fresh
        ));
        // The RESIDUAL class the ref-gate can't reap (concierge audit): an OLD note that's a prose-only
        // drop (empty structured ref) OR a diagnostic → AGE-ARCHIVABLE past the 24h threshold.
        assert!(informational_msg_is_spent(
            "note",
            "DROP 3 superseded v-inference MRs",
            "",
            &queued,
            old
        ));
        assert!(informational_msg_is_spent(
            "note",
            "Isolation aid: wasm 6868/44/0 diagnostic",
            "",
            &queued,
            old
        ));
        // A drop-directive note with an EMPTY ref, still FRESH → NOT reaped yet (waits out the age gate).
        assert!(!informational_msg_is_spent(
            "note",
            "DROP-REF (no ref field)",
            "",
            &queued,
            fresh
        ));
        // An actionable kind is never in this informational path, but defensively → NOT spent (even old).
        assert!(!informational_msg_is_spent(
            "assign",
            "do the thing",
            "",
            &queued,
            old
        ));
        assert!(!informational_msg_is_spent(
            "merge-request",
            "land me",
            "abc",
            &queued,
            old
        ));
    }

    #[test]
    fn parse_failing_subchecks_names_the_failed_derivations_excluding_local_gate() {
        // Real-shape nix output: a failed sub-check's builder line + the local-gate dependency summary.
        let out = "\
building '/nix/store/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-codegen.drv'...
error: builder for '/nix/store/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb-wasm-runtime-build.drv' failed with exit code 1
error: builder for '/nix/store/cccccccccccccccccccccccccccccccc-corpus-09-functions.drv' failed
error: 1 dependency of '/nix/store/dddddddddddddddddddddddddddddddd-local-gate.drv' failed";
        let got = parse_failing_subchecks(out);
        // Names extracted (hash prefix + .drv stripped), multi-hyphen names intact, local-gate EXCLUDED.
        assert_eq!(got, vec!["wasm-runtime-build", "corpus-09-functions"]);
        // Clean run → nothing.
        assert!(parse_failing_subchecks("building '…'\nok: local-gate\n").is_empty());
        // De-dup: the same failing check reported twice → once.
        let dup = "error: builder for '/nix/store/eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee-oracle.drv' failed\n\
                   error: builder for '/nix/store/ffffffffffffffffffffffffffffffff-oracle.drv' failed";
        assert_eq!(parse_failing_subchecks(dup), vec!["oracle"]);
    }

    #[test]
    fn nix_gate_argv_pins_the_load_and_hygiene_critical_flags() {
        // nix_gate_argv is the SINGLE source of truth for the authoritative local-gate `nix build`
        // (run_gate_local + run_gate_local_bounded), so a silent drop of a flag here regresses the whole
        // fleet. Pin the invariants so a refactor/merge can't quietly remove one:
        let argv = nix_gate_argv(".#checks.aarch64-linux.local-gate");
        // Shape: it BUILDS the given target.
        assert_eq!(argv[0], "build");
        assert_eq!(argv[1], ".#checks.aarch64-linux.local-gate");
        // --no-link/--print-out-paths: no gcroot + emit the out-paths the drain/CLI consume.
        assert!(argv.iter().any(|a| a == "--no-link"));
        assert!(argv.iter().any(|a| a == "--print-out-paths"));
        // --keep-going (#5304 gate-hygiene): a RED gate must build ALL constituents so one run names the
        // FULL failing set (feeds parse_failing_subchecks) — never abort at the first failure.
        assert!(
            argv.iter().any(|a| a == "--keep-going"),
            "gate-local must pass --keep-going so one red run surfaces every failing sub-check"
        );
        // --max-jobs <NIX_GATE_MAX_JOBS>: the derivation-parallelism cap that keeps one gate from melting
        // the box (load-85 saturation). The flag and its value MUST stay ADJACENT (nix pairs them).
        let mj = argv.iter().position(|a| a == "--max-jobs").expect(
            "gate-local must cap --max-jobs (derivation-parallelism cap; load-melt protection)",
        );
        assert_eq!(
            argv.get(mj + 1).map(String::as_str),
            Some(NIX_GATE_MAX_JOBS),
            "--max-jobs must be immediately followed by NIX_GATE_MAX_JOBS"
        );
        // --option eval-cache false (stale-nix fix): the gate must FORCE a fresh evaluation, or a dirty
        // tree's under-invalidated eval-cache serves a stale derivation graph → the local corpus gate
        // silently passes on stale results. The three tokens MUST stay adjacent + in order (nix parses
        // `--option <name> <value>`).
        let opt = argv.iter().position(|a| a == "--option").expect(
            "gate-local must disable the eval-cache (dirty-tree stale-derivation fix) via --option",
        );
        assert_eq!(
            (
                argv.get(opt + 1).map(String::as_str),
                argv.get(opt + 2).map(String::as_str)
            ),
            (Some("eval-cache"), Some("false")),
            "--option must be immediately followed by `eval-cache false`"
        );
    }

    #[test]
    fn reconcile_cpu_monitor_cron_installs_heals_and_is_idempotent() {
        let want = cpu_monitor_cron_line("/hub/.claude/fleet/cpu-monitor.sh");
        // Empty crontab → install the line (with a trailing newline for crontab).
        let out = reconcile_cpu_monitor_cron("", &want).expect("installs when absent");
        assert!(out.contains(&want));
        assert!(out.ends_with('\n'));
        // Verbatim already present → no-op (None), so `up` never rewrites the crontab needlessly.
        assert!(reconcile_cpu_monitor_cron(&format!("{want}\n"), &want).is_none());
        // Unrelated entries preserved + a STALE fleet:cpu-monitor line (old hub path) drift-healed.
        let existing = "0 5 * * * /usr/bin/backup\n\
                        */2 * * * * bash /OLD/hub/cpu-monitor.sh >/dev/null 2>&1 # fleet:cpu-monitor\n\
                        @reboot /usr/bin/thing";
        let healed = reconcile_cpu_monitor_cron(existing, &want).expect("heals a stale entry");
        assert!(
            healed.contains("/usr/bin/backup"),
            "preserves unrelated entries"
        );
        assert!(
            healed.contains("@reboot /usr/bin/thing"),
            "preserves unrelated entries"
        );
        assert!(healed.contains(&want), "installs the current hub path");
        assert!(!healed.contains("/OLD/hub/"), "drops the stale hub path");
        assert_eq!(
            healed
                .lines()
                .filter(|l| l.contains("# fleet:cpu-monitor"))
                .count(),
            1,
            "exactly one fleet:cpu-monitor line after heal (no duplicates)"
        );
    }

    #[test]
    fn claude_link_action_links_absent_heals_stale_refuses_realdir_and_is_idempotent() {
        use ClaudeLinkAction::*;
        let want = PathBuf::from("../skills");
        let other = PathBuf::from("../OLD-skills");
        // No tracked source dir → nothing to do, regardless of the link state.
        assert_eq!(
            claude_link_action(false, false, None, false, &want),
            SkipNoSource
        );
        // Correct symlink already present → no-op (idempotent; `up` re-runs every relaunch).
        assert_eq!(
            claude_link_action(true, true, Some(&want), true, &want),
            AlreadyLinked
        );
        // Absent → create the link.
        assert_eq!(claude_link_action(true, false, None, false, &want), Relink);
        // A stale/wrong symlink (old target) → replace it (a symlink owns no content).
        assert_eq!(
            claude_link_action(true, true, Some(&other), true, &want),
            Relink
        );
        // A REAL directory sits there → REFUSE (never delete the user's content).
        assert_eq!(
            claude_link_action(true, false, None, true, &want),
            RefuseRealDir
        );
    }

    #[test]
    fn reconcile_tagged_crons_installs_heals_dedups_and_is_idempotent() {
        let want = prune_cron_lines("/hub/prune-tmp-inodes.sh", "/hub/prune-stale-targets.sh");
        let tmp_line = &want[0].1;
        let tgt_line = &want[1].1;
        // The cron lines carry the concierge-specified cadence + always-on-low setting.
        assert!(tmp_line.starts_with(
            "*/15 * * * * INODE_THRESHOLD_PCT=0 bash /hub/prune-tmp-inodes.sh --apply"
        ));
        assert!(tgt_line.starts_with("0 */6 * * * bash /hub/prune-stale-targets.sh --apply"));

        // Empty crontab → installs BOTH lines, trailing newline.
        let out = reconcile_tagged_crons("", &want).expect("installs when absent");
        assert!(out.contains(tmp_line) && out.contains(tgt_line));
        assert!(out.ends_with('\n'));

        // Both present verbatim (alongside the cpu-monitor + unrelated lines) → no-op.
        let full = format!(
            "0 5 * * * /usr/bin/backup\n\
             */2 * * * * bash /hub/cpu-monitor.sh >/dev/null 2>&1 # fleet:cpu-monitor\n\
             {tmp_line}\n{tgt_line}\n"
        );
        assert!(
            reconcile_tagged_crons(&full, &want).is_none(),
            "verbatim-present (both) → no needless rewrite"
        );

        // One absent → rewrite installs the missing one, keeps the present one + unrelated + cpu-monitor.
        let one_missing = format!(
            "*/2 * * * * bash /hub/cpu-monitor.sh >/dev/null 2>&1 # fleet:cpu-monitor\n{tmp_line}\n"
        );
        let healed =
            reconcile_tagged_crons(&one_missing, &want).expect("installs the missing line");
        assert!(
            healed.contains(tgt_line),
            "installs the absent stale-targets line"
        );
        assert!(
            healed.contains("# fleet:cpu-monitor"),
            "preserves the unrelated cpu-monitor line"
        );

        // STALE drift (old hub path) + a DUPLICATE tagged line → heal to exactly one of each, current path.
        let drifted = format!(
            "0 5 * * * /usr/bin/backup\n\
             */30 * * * * INODE_THRESHOLD_PCT=0 bash /OLD/prune-tmp-inodes.sh --apply >/dev/null 2>&1 # fleet:prune-tmp-inodes\n\
             {tmp_line}\n{tgt_line}\n"
        );
        let h2 = reconcile_tagged_crons(&drifted, &want).expect("heals stale/dup");
        assert!(
            h2.contains("/usr/bin/backup"),
            "preserves unrelated entries"
        );
        assert!(
            !h2.contains("/OLD/prune-tmp-inodes.sh"),
            "drops the stale hub path"
        );
        assert_eq!(
            h2.lines()
                .filter(|l| l.contains("# fleet:prune-tmp-inodes"))
                .count(),
            1,
            "exactly one prune-tmp-inodes line after heal (dedup)"
        );
        assert_eq!(
            h2.lines()
                .filter(|l| l.contains("# fleet:prune-stale-targets"))
                .count(),
            1,
            "exactly one prune-stale-targets line"
        );
    }

